def run_script(script_path: Path, python_exec: str) -> subprocess.CompletedProcess:
    """
    Execute the target script in a subprocess with strict isolation.

    Args:
        script_path: Absolute path to hello_world.py
        python_exec: Python interpreter path

    Returns:
        CompletedProcess with captured stdout/stderr and return code
    """
    return subprocess.run(
        [python_exec, str(script_path)],
        capture_output=True,
        text=True,
        encoding=ENCODING,
        timeout=TIMEOUT_SECONDS,
        cwd=script_path.parent,  # isolate working directory
        env={"PATH": os.environ.get("PATH", "")},  # minimal environment
        check=False,
    )


