class TestEnvironmentIsolation:
    """Validate script independence from external state."""

    def test_no_module_imports(self, script_path):
        """Source must not import any modules (pure stdlib-free execution)."""
        source = script_path.read_text(encoding=ENCODING)
        assert "import" not in source, (
            "Script contains imports; expected zero-dependency implementation"
        )

    def test_no_file_system_writes(self, script_path, tmp_path):
        """Script must not create or modify files in its directory."""
        import hashlib

        # Snapshot directory state before execution
        before = {
            p.name: hashlib.sha256(p.read_bytes()).hexdigest()
            for p in script_path.parent.iterdir()
            if p.is_file()
        }

        result = run_script(script_path, sys.executable)
        assert result.returncode == 0

        # Verify no new files and no modified existing files
        after = {
            p.name: hashlib.sha256(p.read_bytes()).hexdigest()
            for p in script_path.parent.iterdir()
            if p.is_file()
        }
        assert before == after, "Script modified filesystem state"


class TestExecutionGuards:
    """Validate subprocess execution robustness."""

    def test_timeout_guard(self, script_path, python_executable):
        """Script must complete well within the timeout window."""
        import time

        start = time.monotonic()
        run_script(script_path, python_executable)
        elapsed = time.monotonic() - start
        assert elapsed < TIMEOUT_SECONDS, (
            f"Execution took {elapsed:.2f}s, exceeding timeout guard"
        )

    def test_script_syntax_valid(self, script_path):
        """Source must compile without syntax errors."""
        source = script_path.read_text(encoding=ENCODING)
        compile(source, str(script_path), "exec")  # raises SyntaxError if invalid

    def test_script_is_utf8_encoded(self, script_path):
        """File must be valid UTF-8 without BOM."""
        raw = script_path.read_bytes()
        assert not raw.startswith(b"\xef\xbb\xbf"), "File contains UTF-8 BOM"
        raw.decode(ENCODING)  # raises UnicodeDecodeError if invalid


